effect.shader:
void main(){
    vec2 uv=acScreenNorm;
    if(uv.y > level){
        gl_FragColor=texture2DCv(inputImg.texture, uv);
        return;
    }
    float depth=(level-uv.y)/max(level,0.001);
    float wob=sin((uv.x*30.0)+(acTime*speed)+depth*10.0)*0.01*ripple*depth;
    wob+=sin((uv.x*12.0)-(acTime*speed*0.7))*0.012*ripple*depth;
    vec2 ruv=vec2(uv.x+wob, level + (level-uv.y));
    vec4 col=texture2DCv(inputImg.texture, clamp(ruv,0.0,1.0));
    vec3 tint=mix(col.rgb, vec3(0.2,0.45,0.6), 0.35*depth);
    float fres=pow(depth,0.5)*0.3;
    gl_FragColor=vec4(tint+fres, 1.0);
}
